text:
{
  "recommendations": [
    {
      "rec_id": "r1",
      "rationale": [
        {
          "text": "NIR has documented application to tracking major components such as glucose.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p16-nir-major-components"]
        },
        {
          "text": "Transmission or transflection probes are listed for liquid and colloidal samples.",
          "claim_type": "AFS",
          "evidence_ids": ["TABLE-nir_transmission_or_transflection_probe"]
        }
      ],
      "conditions": [
        {
          "text": "Quantitative NIR analysis requires chemometric calibration because its broad absorption bands overlap.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p10-nir-chemometrics"]
        }
      ],
      "limitations": [
        {
          "text": "NIR may lack the sensitivity needed for trace components.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p16-nir-major-components"]
        },
        {
          "text": "Whether NIR can report viable biomass in this fermentation remains unknown.",
          "claim_type": "UNKNOWN",
          "evidence_ids": []
        }
      ]
    },
    {
      "rec_id": "r2",
      "rationale": [
        {
          "text": "Raman is suited to aqueous media because water interferes less than in infrared methods.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p16-raman-aqueous"]
        },
        {
          "text": "The weak Raman effect requires a specialised probe.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p05-raman-weak"]
        }
      ],
      "conditions": [
        {
          "text": "The aqueous-medium rationale assumes that the fermentation liquid is water-based, which must be confirmed.",
          "claim_type": "ASSUMPTION",
          "evidence_ids": []
        }
      ],
      "limitations": [
        {
          "text": "Fluorescence background can overwhelm Raman signals from many organic compounds.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p11-raman-fluorescence"]
        }
      ]
    },
    {
      "rec_id": "r3",
      "rationale": [
        {
          "text": "UV-Vis provides a basis for comparison because suspension turbidity correlates with cell density.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p16-uvvis-biomass"]
        }
      ],
      "conditions": [],
      "limitations": [
        {
          "text": "Turbidity tracks cell density, not cell viability.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p16-uvvis-biomass"]
        },
        {
          "text": "Whether the specified ATR geometry can provide a useful signal for the requested targets remains unknown.",
          "claim_type": "UNKNOWN",
          "evidence_ids": []
        }
      ]
    },
    {
      "rec_id": "r4",
      "rationale": [
        {
          "text": "Most chemicals do not fluoresce, so fluorimetry requires a fluorescent species.",
          "claim_type": "AFS",
          "evidence_ids": ["S01-p05-fluorescence-not-general"]
        },
        {
          "text": "You have not identified a fluorescent target, marker or reference relationship for the requested measurements.",
          "claim_type": "CLIENT",
          "evidence_ids": []
        }
      ],
      "conditions": [],
      "limitations": [
        {
          "text": "The fluorimetric probe is rated as having low selectivity despite high sensitivity.",
          "claim_type": "AFS",
          "evidence_ids": ["TABLE-fluorescence_fluorimetric_probe"]
        }
      ]
    }
  ],
  "premise_checks": [
    {
      "premise_id": "p0",
      "explanation": [
        {
          "text": "Suitability of the existing fluorescence spectrometer for these outputs remains unverifiable without an established fluorescent target or justified indicator relationship.",
          "claim_type": "UNKNOWN",
          "evidence_ids": []
        }
      ]
    },
    {
      "premise_id": "p1",
      "explanation": [
        {
          "text": "With no target, marker or reference relationship identified, a link between fluorescence and either requested variable remains unverifiable.",
          "claim_type": "UNKNOWN",
          "evidence_ids": []
        }
      ]
    }
  ],
  "direct_answer": [
    {
      "text": "Do not use the existing fluorescence instrument to report glucose concentration or viable biomass directly on the current justification.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    },
    {
      "text": "Treat the alternative methods as provisional feasibility candidates, not validated solutions for these outputs.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ],
  "verdict": "CONDITIONAL"
}
